Rewrite the following GNU C++14 code into exactly 5 different variants. The code reads and writes I/O from the console. Each variant should have the exact same functionality as the given code, meaning that it should have the same output for any given input. Make the variants meaningfully different from one another and from the original code, while preserving functionality exactly.
Print all 5 rewritten variants, numbered from 1 to 5. Do not stop early, do not skip an index, and do not repeat an index. Use this exact format:
<perturbed_code_1>
<your_rewritten_code_1>
</perturbed_code_1>
<perturbed_code_2>
<your_rewritten_code_2>
</perturbed_code_2>
<perturbed_code_3>
<your_rewritten_code_3>
</perturbed_code_3>
<perturbed_code_4>
<your_rewritten_code_4>
</perturbed_code_4>
<perturbed_code_5>
<your_rewritten_code_5>
</perturbed_code_5>
Each block must contain one complete program. Do not provide any other text or markdown fences.

Here is the original GNU C++14 code you have to rewrite:
<original_code>
#include <cstdio>
#include <cstring>
#include <algorithm>
#define fo(i,a,b) for(int i=a;i<=b;i++)
#define fd(i,a,b) for(int i=a;i>=b;i--)
using namespace std;

typedef long long ll;

const int N=262144;

int L,n,k,Mo,len,bit[20],fac[N],inv[N],cnt[N],g[20][N],f[20][N];

int pwr(int x,int y) {
	int z=1;
	for(;y;y>>=1,x=(ll)x*x%Mo)
		if (y&1) z=(ll)z*x%Mo;
	return z;
}

void inc(int &x,int y) {x=x+y>=Mo?x+y-Mo:x+y;}
void dec(int &x,int y) {x=x-y<0?x-y+Mo:x-y;}
void FWT(int *a,int len) {for(int i=1;i<len;i<<=1) for(int j=0;j<len;j+=i<<1) for(int k=0;k<i;k++) inc(a[j+k+i],a[j+k]);}
void IFWT(int *a,int len) {for(int i=1;i<len;i<<=1) for(int j=0;j<len;j+=i<<1) for(int k=0;k<i;k++) dec(a[j+k+i],a[j+k]);}

ll h[20],p[20];

void get_ln() {
	p[0]=0;
	fo(i,1,n) {
		p[i]=h[i]*i;
		fo(j,1,i-1) p[i]-=p[j]*h[i-j]%Mo*j;
		p[i]=p[i]%Mo*inv[i]%Mo;
	}
	fo(i,0,n) h[i]=(p[i]+Mo)%Mo;
}

void get_exp() {
	p[0]=1;
	fo(i,1,n) {
		p[i]=0;
		fo(j,1,i) p[i]+=h[j]*p[i-j]%Mo*j;
		p[i]=p[i]%Mo*inv[i]%Mo;
	}
	fo(i,0,n) h[i]=p[i];
}

int main() {
	scanf("%d%d%d",&L,&k,&Mo);
	int all=pwr(k,L);
	if (L&1) {
		//puts("0");
		printf("%d\n",all);
		return 0;
	}
	fac[0]=1;fo(i,1,L) fac[i]=(ll)fac[i-1]*i%Mo;
	inv[L]=pwr(fac[L],Mo-2);fd(i,L-1,0) inv[i]=(ll)inv[i+1]*(i+1)%Mo;
	fo(s,1,L) cnt[s]=cnt[s^(s&-s)]+1;
	fo(i,0,18) if (L>>i&1) bit[++n]=1<<i;
	len=1<<n;
	fo(i,0,len-1) {
		int s=0;
		fo(j,1,n) if (i>>(j-1)&1) s+=bit[j];
		g[cnt[i]][i]=inv[s];
	}
	fo(i,2,n) inv[i]=(ll)(Mo-Mo/i)*inv[Mo%i]%Mo;
	fo(i,0,n) FWT(g[i],len);
	fo(s,0,len-1) {
		fo(i,0,n) h[i]=g[i][s];
		get_ln();
		fo(i,0,n) h[i]=h[i]*k;
		get_exp();
		fo(i,0,n) f[i][s]=h[i];
	}
	IFWT(f[n],len);
	int ans=(ll)f[n][len-1]*fac[L]%Mo;
	ans=(all-ans+Mo)%Mo;
	printf("%d\n",ans);
	return 0;
}
</original_code>
